  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Cerivastatin, which shares the same 3,5-dihydroxyhept-6-enoic acid statin side chain and a fluorophenyl-substituted heteroaromatic core, has an absolute oral bioavailability of 60% in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Trovafloxacin, a fluorophenyl-substituted heteroaromatic carboxylic acid with high assay transfer, has 88% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Paltusotine has 69% absolute oral bioavailability in healthy participants, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ketanserin has 49.3% absolute oral bioavailability in young volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Haloperidol has 60-70% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Sacubitril has ≥60% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone ER has 28% absolute oral bioavailability, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Propranolol has 15.8% absolute oral bioavailability in normal volunteers, a low-F outlier driven by extensive first-pass metabolism of a basic beta-blocker scaffold; this is outweighed by the consistent high-F evidence from more relevant analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pitavastatin-like statin acid. The closest analogue, cerivastatin, has 60% absolute oral bioavailability, and multiple other high-transfer analogues with direct human absolute F measurements are at or above 20%, most well above. The only sub-20% record (propranolol) reflects a mechanistically different basic beta-blocker with high first-pass metabolism and does not outweigh the strong high-F evidence.",
  "evidence_gaps": [
    "No direct pitavastatin bioavailability record is present in the supplied evidence; reliance is on the close statin analogue cerivastatin and other high-F compounds.",
    "No specific formulation or food-effect data for the query molecule are provided.",
    "The impact of full ionization at physiological pH on the query's permeability is not directly measured, but the statin analogue evidence indicates this does not preclude high oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

